"""Run this installation's dftracer_install_info without loading the tracer."""

import subprocess
import sys
from pathlib import Path


def script_path():
    """The script CMake generated and installed next to this package."""
    package_dir = Path(__file__).resolve().parent
    candidate = package_dir / "bin" / "dftracer_install_info"
    if candidate.is_file():
        return candidate
    raise FileNotFoundError(
        "dftracer_install_info not found at {}. It is generated by the CMake "
        "build; reinstall DFTracer, or run <prefix>/bin/dftracer_install_info "
        "for a native installation.".format(candidate)
    )


def main(argv=None):
    try:
        script = script_path()
    except FileNotFoundError as error:
        print("dftracer_install_info: {}".format(error), file=sys.stderr)
        return 1
    args = sys.argv[1:] if argv is None else argv
    return subprocess.call([sys.executable, str(script)] + list(args))


if __name__ == "__main__":
    sys.exit(main())
